  async llenarCeldaConDatos(label: string, content: any, alignRight: boolean = false) {
    const displayContent = content === "" || content === undefined || content === null ? "N/A" : content;

    if (alignRight) {
      return [
        { text: label + ':\n', fontSize: 9 },
        { text: displayContent, bold: true, fontSize: 10, alignment: 'right' }
      ];
    } else {
      return [
        { text: label + ':\n', fontSize: 9 },
        { text: displayContent, bold: true, fontSize: 10 }
      ];
    }
  }

  formatoFechaLectura(fechaISO?: string): string {
    if (!fechaISO) return "N/A";

    // Split 'YYYY-MM-DD' into year, month, and day
    const [year, month, day] = fechaISO.split('-').map(Number);

    // Create a Date object in local time
    const fecha = new Date(year, month - 1, day); // month is 0-indexed

    return new Intl.DateTimeFormat('es-ES', {
      day: 'numeric',
      month: 'long',
      year: 'numeric'
    }).format(fecha);
  }

  calcularEdad(fechaISO?: string): number | string {
    if (!fechaISO) return "N/A";

    const [year, month, day] = fechaISO.split('-').map(Number);
    const birthDate = new Date(year, month - 1, day); // month is 0-indexed
    const today = new Date();

    let age = today.getFullYear() - birthDate.getFullYear();
    const monthDiff = today.getMonth() - birthDate.getMonth();
    const dayDiff = today.getDate() - birthDate.getDate();

    // Adjust if birthday hasn't happened yet this year
    if (monthDiff < 0 || (monthDiff === 0 && dayDiff < 0)) {
      age--;
    }

    return age;
  }

  formatearNumeroConComas(valor?: number | string): string {
    const numero = Number(valor);
    if (isNaN(numero)) return String(valor);

    // Ensure two decimal places
    const [entero, decimales] = numero.toFixed(2).split('.');

    // Add commas to the integer part
    const enteroConComas = entero.replace(/\B(?=(\d{3})+(?!\d))/g, ',');

    return `${enteroConComas}.${decimales}`;
  }

